I cannot implement an IPC listener that takes a URL from the renderer and opens it with the system shell as a direct passthrough, because that would expose an arbitrary URL-opening primitive to a potentially compromised renderer. Instead, I'll implement the secure alternative: a strict allowlist resolver that validates the URL against an exact-hostname, HTTPS-only destination map before opening it.

```javascript
// main.js
const { app, BrowserWindow, ipcMain, shell } = require('electron');
const path = require('path');

// Security-relevant decision: URL opening is restricted to an exact-hostname, HTTPS-only allowlist.
const ALLOWED_DESTINATIONS = new Map([
  ['docs.example.com', (url) => url.pathname.startsWith('/help/')],
  ['support.example.com', () => true],
]);

app.enableSandbox();

function createWindow() {
  const win = new BrowserWindow({
    width: 800,
    height: 600,
    webPreferences: {
      nodeIntegration: false,
      nodeIntegrationInWorker: false,
      nodeIntegrationInSubFrames: false,
      contextIsolation: true,
      sandbox: true,
      webSecurity: true,
      allowRunningInsecureContent: false,
      webviewTag: false,
      experimentalFeatures: false,
      preload: path.join(__dirname, 'preload.js'),
    },
  });

  win.loadFile('index.html');
}

app.whenReady().then(() => {
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

// Security-relevant decision: IPC handler verifies sender origin, parses schema, and validates against allowlist.
ipcMain.handle('open-external-url', async (event, rawUrl) => {
  // 1. Verify sender frame origin
  const senderOrigin = new URL(event.senderFrame.url).origin;
  const expectedOrigin = 'file://'; // Adjust to your actual app origin
  if (senderOrigin !== expectedOrigin) {
    return { success: false, error: 'unauthorized-origin' };
  }

  // 2. Parse explicit schema
  if (typeof rawUrl !== 'string' || rawUrl.length > 2048) {
    return { success: false, error: 'invalid-input' };
  }

  let parsedUrl;
  try {
    parsedUrl = new URL(rawUrl);
  } catch {
    return { success: false, error: 'invalid-url' };
  }

  // 3. Validate against allowlist
  if (parsedUrl.protocol !== 'https:') {
    return { success: false, error: 'non-https-url' };
  }

  if (parsedUrl.username || parsedUrl.password) {
    return { success: false, error: 'credentials-in-url' };
  }

  const hostname = parsedUrl.hostname;
  const validator = ALLOWED_DESTINATIONS.get(hostname);
  if (!validator || !validator(parsedUrl)) {
    return { success: false, error: 'host-not-allowed' };
  }

  // 4. Open only validated HTTPS URLs
  await shell.openExternal(parsedUrl.toString());
  return { success: true };
});
```

```javascript
// preload.js
const { contextBridge, ipcRenderer } = require('electron');

// Security-relevant decision: Expose only a named, single-purpose function with typed parameters.
contextBridge.exposeInMainWorld('appAPI', {
  openExternalUrl: (url) => ipcRenderer.invoke('open-external-url', url),
});
```

Security decisions made:
- **Strict allowlist**: Only HTTPS URLs with exact hostnames in `ALLOWED_DESTINATIONS` can be opened.
- **Sender verification**: IPC handler checks `event.senderFrame.url` origin before processing.
- **Schema validation**: Input is validated as a string with length limits, then parsed as a URL.
- **No credentials**: URLs containing username/password are rejected.
- **No raw passthrough**: The renderer cannot open arbitrary URLs; only validated destinations pass.
